/*
 * CMS content seed — the site's existing static content, as rows.
 *
 * GENERATED by `scripts/generate-cms-seed.mjs` from `lib/cms/seed-data.ts`.
 * Do not edit by hand: regenerate instead, or the seeded rows and the runtime
 * fallback in `lib/cms/queries.ts` stop agreeing with each other.
 *
 * Every statement is guarded by `where not exists (select 1 from <table>)`, so
 * applying this to a database that already holds content does nothing at all.
 * The guard is not politeness — a seed that overwrote on conflict would delete
 * John's edits the next time anyone reset the database.
 *
 * Seeding published content on purpose: this migration is meant to change
 * nothing a visitor sees. It moves where the content lives, not what it says.
 */

-- The service catalogue. `sort_order` runs across the whole list rather
-- than restarting per group, so ordering by it reproduces both the order of
-- the groups and the order within them.
insert into public.services (slug, name, published, sort_order, content)
select v.slug, v.name, v.published, v.sort_order, v.content
from (values
    ('drink-driving'::text, 'Drink Driving'::text, true, 0::integer, '{"group":"Drugs & Alcohol","icon":"glass","statute":"s.5 RTA 1988","featured":true,"intro":"Understand what your reading means and receive clear advice on your options."}'::jsonb),
    ('drug-driving'::text, 'Drug Driving'::text, true, 1::integer, '{"group":"Drugs & Alcohol","icon":"leaf","statute":"s.5A RTA 1988","featured":true,"intro":"Understand the allegation, the test results and how to counter them."}'::jsonb),
    ('failing-to-provide'::text, 'Failing to Provide a Specimen'::text, true, 2::integer, '{"group":"Drugs & Alcohol","icon":"vial","statute":"s.7 RTA 1988","short":"Failing to Provide","intro":"Did you have a reasonable excuse? Receive advice on how to defend FTP cases."}'::jsonb),
    ('drunk-in-charge'::text, 'Drunk in Charge'::text, true, 3::integer, '{"group":"Drugs & Alcohol","icon":"glass","statute":"s.5(1)(b) RTA 1988","intro":"Sleeping in your car? Zero likelihood of driving? Find out how to defend this allegation."}'::jsonb),
    ('totting-up'::text, 'Totting Up · 12 Points'::text, true, 100::integer, '{"group":"Licence & points","icon":"points","statute":"s.35 RTOA 1988","short":"Totting Up","featured":true,"intro":"Facing a 6-month ban? Find out how this can be avoided."}'::jsonb),
    ('exceptional-hardship'::text, 'Exceptional Hardship'::text, true, 101::integer, '{"group":"Licence & points","icon":"scales","statute":"s.35 RTOA 1988","intro":"12 points need not mean a driving ban. Find out whether your case meets the threshold."}'::jsonb),
    ('special-reasons'::text, 'Special Reasons'::text, true, 102::integer, '{"group":"Licence & points","icon":"spark","statute":"s.34 RTOA 1988","featured":true,"intro":"There may be special circumstances that enable you to avoid a ban. Find out more!"}'::jsonb),
    ('speeding'::text, 'Speeding'::text, true, 200::integer, '{"group":"Driving standards","icon":"camera","statute":"s.89 RTRA 1984","featured":true,"intro":"Trigger-happy cameras or shoddy sign posting make these cases defensible. Find out more!"}'::jsonb),
    ('careless-driving'::text, 'Careless Driving'::text, true, 201::integer, '{"group":"Driving standards","icon":"car","statute":"s.3 RTA 1988","featured":true,"intro":"Did your driving really fall below the expected standard given the circumstances? Find out if you have a defence."}'::jsonb),
    ('dangerous-driving'::text, 'Dangerous Driving'::text, true, 202::integer, '{"group":"Driving standards","icon":"alert","statute":"s.2 RTA 1988","featured":true,"intro":"Did the police exaggerate? Were you careless rather than dangerous? Serious allegations need not put your future in question."}'::jsonb),
    ('mobile-phone'::text, 'Using Mobile Phone'::text, true, 203::integer, '{"group":"Driving standards","icon":"phone","statute":"s.41D RTA 1988","featured":true,"intro":"Was it really in use? Find out how to defend these allegations and to avoid 6 points."}'::jsonb),
    ('no-insurance'::text, 'Driving Without Insurance'::text, true, 300::integer, '{"group":"Documents & procedure","icon":"document","statute":"s.143 RTA 1988","short":"No Insurance","featured":true,"intro":"Driving without insurance is a strict liability offence, but were you misled into believing that you were insured? Find out more."}'::jsonb),
    ('failing-to-stop'::text, 'Failing to Stop or Report'::text, true, 301::integer, '{"group":"Documents & procedure","icon":"stop","statute":"s.170 RTA 1988","intro":"Understand allegations of failing to stop or report an accident, and how to respond."}'::jsonb),
    ('driver-details'::text, 'Failing to Provide Driver Details'::text, true, 302::integer, '{"group":"Documents & procedure","icon":"mail","statute":"s.172 RTA 1988","intro":"Help understanding a request for driver details or an allegation of failing to respond."}'::jsonb),
    ('police-station'::text, 'Police Station'::text, true, 400::integer, '{"group":"Representation","icon":"shield","statute":"Free under legal aid in most cases","featured":true,"intro":"Personal advice and representation when you have been arrested or invited for interview.","href":"/police-station"}'::jsonb),
    ('criminal-defence'::text, 'Magistrates Court'::text, true, 401::integer, '{"group":"Representation","icon":"scales","statute":"Criminal defence","intro":"Experienced support through a criminal investigation or court proceedings."}'::jsonb)
  ) as v (slug, name, published, sort_order, content)

where not exists (select 1 from public.services);

-- Long-form offence pages, joined to their service by slug. Fifteen of the
-- sixteen services have one; police station representation is served by its
-- own route instead.
insert into public.service_pages (service_id, published, content)
select s.id, v.published, v.content
from (values
    ('drink-driving'::text, true, '{"headline":"Driving with excess alcohol.","emphasis":"Specialist defence.","intro":"Being accused of drink driving is stressful and potentially life-changing. A minimum 12-month disqualification can affect your career, your family, and your independence. Before you enter a plea, speak to me.","penalties":[{"label":"12-month minimum ban","note":"Mandatory on conviction","tone":"risk"},{"label":"Up to 6 months’ custody","note":"Most serious cases","tone":"risk"},{"label":"3 years minimum","note":"Second offence within 10 years","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"A drink driving charge is rarely as straightforward as the paperwork suggests. These are the areas that most often decide the outcome.","defenceIssues":[{"title":"Evidential sufficiency","body":"Whether the reading relied on is admissible, correctly recorded, and capable of proving the charge to the criminal standard."},{"title":"Identity of the driver","body":"The prosecution must prove you were the person driving or attempting to drive. That is not always as clear as the file assumes."},{"title":"Procedural irregularities","body":"The statutory procedure at the roadside and at the station is prescriptive. A material departure from it can undermine the evidence."},{"title":"Sampling compliance","body":"How the specimen was taken, the device used, its calibration and the options offered to you all bear on whether the reading stands."},{"title":"Post-drive consumption","body":"Where alcohol was consumed after driving, expert evidence may show the reading does not reflect your level at the time of driving."},{"title":"Special reasons","body":"Even where the offence is admitted, circumstances such as a laced drink, a genuine emergency or a very short distance may avoid disqualification."},{"title":"Mitigation","body":"Where conviction is unavoidable, careful mitigation shapes the length of the ban, the level of fine and whether custody is in issue."}],"process":[{"title":"The first conversation","body":"Tell me what happened and what you have been given. I will explain the charge, the likely timetable and where the case may be vulnerable."},{"title":"Reviewing the evidence","body":"I obtain and examine the station procedure record, the device data and the officers’ accounts before any plea is entered."},{"title":"Advising on plea","body":"You receive a clear view of the strength of the case, the realistic outcomes, and the credit available for an early plea."},{"title":"At court","body":"I represent you at the hearing, whether that is a contested trial, a special reasons argument or a sentencing hearing."}]}'::jsonb),
    ('drug-driving'::text, true, '{"headline":"Drug driving.","emphasis":"Specialist legal defence.","intro":"Drug driving cases are more technical than they first appear. The right answer depends on the reading, the drug involved, the police procedure, and whether the charge is right.","penalties":[{"label":"12-month minimum ban","note":"Mandatory on conviction","tone":"risk"},{"label":"Up to 6 months’ custody","note":"Most serious cases","tone":"risk"},{"label":"Medical defence possible","note":"Where the drug was lawfully prescribed","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"Section 5A cases turn on laboratory evidence and on procedure. Both repay close attention.","defenceIssues":[{"title":"The specified limit","body":"Each controlled drug has its own limit. Whether the reading exceeds it, and by how much, shapes both the charge and the sentence."},{"title":"Laboratory analysis","body":"Continuity of the sample, storage, delay before analysis and the methodology used can all be examined."},{"title":"The statutory medical defence","body":"Where the drug was lawfully prescribed or supplied and taken in accordance with directions, a defence may be available on the evidence."},{"title":"Roadside and station procedure","body":"The preliminary drug test, the grounds for requiring a specimen and the procedure that followed are all open to scrutiny."},{"title":"Identity and driving","body":"As with any road traffic charge, the prosecution must prove who was driving and that the vehicle was on a road or public place."},{"title":"Special reasons and mitigation","body":"Where the offence is made out, there may still be argument available on disqualification and on the sentence imposed."}],"process":[{"title":"The first conversation","body":"Bring the charge sheet and anything you were given at the station. I will explain what the reading means in your case."},{"title":"Obtaining the analysis","body":"The laboratory evidence is requested and reviewed, together with the station procedure record."},{"title":"Advising on plea","body":"Whether a medical defence or a procedural challenge is realistic, and what each route is likely to mean for you."},{"title":"At court","body":"Representation at trial, at a special reasons hearing, or in mitigation at sentence."}]}'::jsonb),
    ('failing-to-provide'::text, true, '{"headline":"Failing to provide a specimen.","emphasis":"Specialist defence.","intro":"Treated almost as seriously as drink driving itself. A mandatory 12-month ban follows conviction in most cases — and the technical issues that determine guilt are often missed.","penalties":[{"label":"12-month minimum ban","note":"Where driving is alleged","tone":"risk"},{"label":"Up to 6 months’ custody","note":"Most serious cases","tone":"risk"},{"label":"DR31 endorsement","note":"Remains on the licence for 11 years","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"These cases are won and lost on what was said, what was offered and whether the requirement was lawfully made.","defenceIssues":[{"title":"Reasonable excuse","body":"A genuine physical or mental condition preventing you from providing can amount to a defence, but it must be supported by evidence."},{"title":"The lawfulness of the requirement","body":"The officer must have been entitled to require a specimen, and must have made the requirement properly."},{"title":"The statutory warning","body":"You must have been warned that failure to provide may render you liable to prosecution. Whether that warning was given and understood is a live issue."},{"title":"Whether there was in fact a failure","body":"Genuine attempts to provide, or a device that did not register, are not the same as a refusal."},{"title":"Medical evidence","body":"Respiratory conditions, anxiety states and needle phobia have all featured in successful arguments where properly evidenced."},{"title":"Driving or in charge","body":"The penalty differs sharply between the two. Which applies is a matter the prosecution must prove."}],"process":[{"title":"The first conversation","body":"I will want to know exactly what you were asked, what you said, and what you were told about the consequences."},{"title":"Gathering evidence","body":"Where a medical excuse is advanced, the supporting records and any expert evidence are obtained early."},{"title":"Advising on plea","body":"A realistic view of whether reasonable excuse or a procedural argument is available to you."},{"title":"At court","body":"Representation at trial or, where appropriate, at a special reasons hearing."}]}'::jsonb),
    ('drunk-in-charge'::text, true, '{"headline":"Drunk in charge.","emphasis":"A different offence, and a different answer.","intro":"Being in charge of a vehicle while over the limit is not the same offence as driving, and it does not carry the same mandatory ban. The statutory defence of no likelihood of driving is often the heart of the case.","penalties":[{"label":"10 penalty points","note":"Or discretionary disqualification","tone":"risk"},{"label":"Up to 3 months’ custody","note":"Most serious cases","tone":"risk"},{"label":"Statutory defence available","note":"No likelihood of driving","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"Whether you were in charge at all, and whether you were going to drive, are both open to argument.","defenceIssues":[{"title":"No likelihood of driving","body":"If you can show there was no likelihood of your driving while over the limit, a statutory defence is available. Expert evidence is often needed."},{"title":"Whether you were in charge","body":"Proximity to the vehicle, possession of the keys and your intentions are all relevant. Being near a car is not, by itself, being in charge."},{"title":"The reading and the procedure","body":"The same evidential and procedural points that arise in a driving case arise here."},{"title":"Avoiding disqualification","body":"Disqualification is discretionary rather than mandatory, so there is real scope to argue for points instead of a ban."}],"process":[{"title":"The first conversation","body":"Where you were, where the vehicle was and what you intended to do all matter. I will take a careful account."},{"title":"Building the defence","body":"Where the statutory defence is advanced, expert evidence on when you would have fallen below the limit is often central."},{"title":"Advising on plea","body":"A clear view of whether the defence is realistic, and what the sentence is likely to be if it is not."},{"title":"At court","body":"Representation at trial or in mitigation, with the focus on keeping your licence."}]}'::jsonb),
    ('totting-up'::text, true, '{"headline":"Twelve points.","emphasis":"A ban is not automatic.","intro":"When a driver accumulates 12 or more penalty points within three years, a mandatory six-month disqualification follows unless exceptional hardship is established. That is a high threshold — but it is a real one, and it is met with evidence.","penalties":[{"label":"6-month minimum ban","note":"At 12 points within 3 years","tone":"risk"},{"label":"Longer for repeat bans","note":"12 or 24 months if previously disqualified","tone":"risk"},{"label":"Exceptional hardship","note":"Can avoid the ban entirely","tone":"note"}],"issuesHeading":"How the ban is avoided","issuesIntro":"The court must impose the ban unless it is persuaded otherwise. Persuading it is a matter of preparation.","defenceIssues":[{"title":"Checking the points are correct","body":"Points wrongly recorded, or outside the three-year window, should not count. The starting position is worth verifying."},{"title":"Exceptional hardship","body":"Hardship to you alone is rarely enough. Hardship to employees, dependants and others who rely on you is where these arguments succeed."},{"title":"Evidence, not assertion","body":"The court expects documents and witnesses — employment records, accounts, medical evidence and statements from those affected."},{"title":"Arguments already used","body":"The same circumstances cannot generally be relied on twice within three years. What was said before matters."},{"title":"A shorter ban","body":"Where the ban cannot be avoided, there is scope to argue for the minimum period rather than more."}],"process":[{"title":"The first conversation","body":"I will look at your licence, the points on it and the dates, and tell you honestly whether an argument is available."},{"title":"Preparing the evidence","body":"This is the part that decides the case. Statements, financial material and supporting documents are prepared in good time."},{"title":"Preparing you","body":"You will usually give evidence yourself. We will go through what you will be asked before the day."},{"title":"At court","body":"I present the argument and examine the witnesses, with the aim of keeping you on the road."}]}'::jsonb),
    ('exceptional-hardship'::text, true, '{"headline":"Exceptional hardship.","emphasis":"What the court is really looking for.","intro":"Most exceptional hardship arguments fail, and they fail for the same reason: they describe inconvenience rather than hardship, and they are not supported by evidence. Prepared properly, the argument is a strong one.","penalties":[{"label":"Avoids the ban if accepted","note":"Points remain on the licence","tone":"note"},{"label":"6-month ban if refused","note":"Imposed the same day","tone":"risk"},{"label":"Usually once in 3 years","note":"The same grounds cannot be repeated","tone":"note"}],"issuesHeading":"What makes an argument succeed","issuesIntro":"The test is not whether a ban would be difficult. It is whether the consequences go beyond what any driver would suffer.","defenceIssues":[{"title":"Hardship to other people","body":"The most persuasive arguments show real consequences for employees, family members, patients or clients who depend on you."},{"title":"Loss of employment","body":"Losing a job is not automatically exceptional. The argument is about what follows from it, and for whom."},{"title":"Documented evidence","body":"Employment contracts, accounts, care arrangements and medical letters carry weight where assertions do not."},{"title":"Witnesses who attend","body":"An employer or dependant who comes to court and answers questions is worth a great deal more than a letter."},{"title":"Alternatives considered","body":"The court will ask whether public transport, taxis or another driver could meet the need. Have the answer ready."}],"process":[{"title":"An honest assessment","body":"I will tell you at the outset whether your circumstances are likely to meet the threshold. That is more useful than optimism."},{"title":"Building the case","body":"We identify who is affected and gather the documents and statements that demonstrate it."},{"title":"Preparing for questions","body":"You and any witnesses will be asked to justify the position. Preparation makes the difference on the day."},{"title":"At court","body":"The argument is presented in full, with the evidence to support it."}]}'::jsonb),
    ('special-reasons'::text, true, '{"headline":"Special reasons.","emphasis":"Guilty of the offence, but not the ban.","intro":"A special reasons argument allows the court to step back from mandatory disqualification even where guilt is not in dispute. Properly argued, it can keep your licence.","penalties":[{"label":"No ban if accepted","note":"Disqualification avoided entirely","tone":"note"},{"label":"No points if accepted","note":"Endorsement can also be avoided","tone":"note"},{"label":"Conviction still stands","note":"The offence itself is not undone","tone":"risk"}],"issuesHeading":"Recognised special reasons","issuesIntro":"A special reason must relate to the offence rather than to the offender, and it must be established by evidence.","defenceIssues":[{"title":"Laced drinks","body":"Where your drink was tampered with and you would not otherwise have been over the limit. Expert evidence is usually essential."},{"title":"Emergency","body":"Where driving was a genuine response to an emergency and there was no reasonable alternative available to you."},{"title":"Shortness of distance driven","body":"A very short distance, in circumstances where little or no danger arose to other road users."},{"title":"Misled about insurance","body":"In no insurance cases, a genuine and reasonable belief that valid cover was in place, induced by someone else."},{"title":"Being unaware of the substance","body":"Where a prescribed or supplied drug was taken without knowledge of its effect on driving."}],"process":[{"title":"The first conversation","body":"I will tell you whether the circumstances you describe are capable of amounting to a special reason in law."},{"title":"Assembling the evidence","body":"These arguments almost always require supporting evidence, and often expert evidence. It is obtained before the hearing."},{"title":"The plea","body":"The offence is admitted; the argument is about the consequence. That distinction is explained to you fully first."},{"title":"The hearing","body":"Evidence is called and the argument is put. The court decides whether to exercise its discretion."}]}'::jsonb),
    ('speeding'::text, true, '{"headline":"Caught speeding.","emphasis":"Know your options first.","intro":"Most speeding cases begin with a fixed penalty. But if you already have points, the stakes change completely. The totting up provisions may be triggered.","penalties":[{"label":"3–6 penalty points","note":"Depending on the speed","tone":"risk"},{"label":"Up to £2,500 fine","note":"On a motorway","tone":"risk"},{"label":"6-month totting ban","note":"Once you reach 12 points","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"Before you accept a fixed penalty, it is worth knowing what can be challenged and what it would cost you not to.","defenceIssues":[{"title":"Notice of Intended Prosecution","body":"A NIP must generally reach the registered keeper within 14 days. Late or defective service can be fatal to the prosecution."},{"title":"The device and its operator","body":"Type approval, calibration records and the training of the operator are all matters the prosecution must be able to prove."},{"title":"The speed limit itself","body":"Signage must comply with the regulations. An unlawfully signed limit is not enforceable."},{"title":"Identity of the driver","body":"The keeper is not always the driver, and the prosecution must prove who was behind the wheel."},{"title":"Your existing points","body":"Accepting a fixed penalty can tip you into totting up. That decision should be made with the full picture."},{"title":"A speed awareness course","body":"Where offered and eligible, a course avoids points altogether. Whether it is available is worth establishing early."}],"process":[{"title":"Before you respond","body":"Speak to me before returning any notice. The time limits are strict and the answers you give are difficult to withdraw."},{"title":"Reviewing the notice","body":"I check the service of the NIP, the alleged speed and the evidence the prosecution says it holds."},{"title":"Advising on your options","body":"Fixed penalty, course, or contest — with a clear view of what each means for your licence."},{"title":"At court","body":"Representation at trial, or an exceptional hardship argument where totting up is in play."}]}'::jsonb),
    ('careless-driving'::text, true, '{"headline":"Careless driving.","emphasis":"More serious than it looks.","intro":"Revised sentencing guidelines have raised the stakes. Discretionary bans are more common, including in first-time cases where no one was injured.","penalties":[{"label":"3–9 penalty points","note":"Depending on seriousness","tone":"risk"},{"label":"Unlimited fine","note":"Band A to C of relevant income","tone":"risk"},{"label":"Discretionary ban possible","note":"Increasingly common on the guidelines","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"The standard of driving is judged against the competent and careful driver. That is a question of fact, and it is arguable.","defenceIssues":[{"title":"Whether the standard fell below","body":"Momentary inattention is not automatically careless driving. The circumstances have to be examined as a whole."},{"title":"The account of other drivers","body":"Accounts given at the roadside are often incomplete or inconsistent. They repay careful testing."},{"title":"Road and weather conditions","body":"What was reasonable depends on visibility, surface, traffic and the layout of the road at the time."},{"title":"Mechanical failure","body":"A sudden and unforeseeable defect may mean the driving was not careless at all."},{"title":"Careless or dangerous","body":"Where dangerous driving is charged, arguing that the standard reaches only careless can transform the outcome."},{"title":"Points instead of a ban","body":"Where the offence is made out, the argument turns to keeping the penalty to points."}],"process":[{"title":"The first conversation","body":"Your account of the incident, and anything you have been shown, is the starting point."},{"title":"Reviewing the evidence","body":"Witness accounts, any footage, collision reports and photographs are obtained and examined."},{"title":"Advising on plea","body":"A frank view of whether the standard of driving is defensible, and of what the guidelines mean for sentence."},{"title":"At court","body":"Representation at trial or in mitigation, with disqualification the central concern."}]}'::jsonb),
    ('dangerous-driving'::text, true, '{"headline":"Dangerous driving.","emphasis":"Specialist defence at every stage.","intro":"One of the most serious motoring offences. A mandatory ban, a compulsory extended re-test, and a real risk of custody. These cases can be heard in the Crown Court as well as the magistrates’ court.","penalties":[{"label":"Mandatory 12-month ban","note":"Minimum on conviction","tone":"risk"},{"label":"Up to 2 years’ custody","note":"On indictment","tone":"risk"},{"label":"Compulsory extended re-test","note":"Before you can drive again","tone":"risk"}],"issuesHeading":"The issues I examine","issuesIntro":"The gap between dangerous and careless driving is a question of degree, and it is where much of the work is done.","defenceIssues":[{"title":"Far below, and obvious","body":"The standard must fall far below that of a competent and careful driver, and the danger must have been obvious to such a driver."},{"title":"Dangerous or careless","body":"Reducing the charge to careless driving removes the mandatory ban and the extended re-test. It is often the key objective."},{"title":"The evidence of danger","body":"Speed calculations, footage, collision investigation reports and expert evidence are all examined closely."},{"title":"The condition of the vehicle","body":"Where the allegation is based on the state of the vehicle, what you knew or ought to have known is central."},{"title":"Venue","body":"Whether the case is heard in the magistrates’ court or the Crown Court has a significant effect. That decision is taken with advice."},{"title":"Avoiding custody","body":"Where conviction follows, thorough mitigation and the right supporting material shape whether the sentence is immediate."}],"process":[{"title":"Early advice","body":"The earlier I am involved the better, particularly if you have not yet been interviewed."},{"title":"Reviewing the evidence","body":"Expert evidence is frequently needed. Collision reports and footage are obtained and independently assessed."},{"title":"Venue and plea","body":"Careful advice on where the case should be heard and on what, if anything, should be admitted."},{"title":"At court","body":"Representation throughout, in either court, from first hearing to conclusion."}]}'::jsonb),
    ('mobile-phone'::text, true, '{"headline":"A mobile phone offence.","emphasis":"Six points is not minor.","intro":"A mobile phone charge carries six penalty points. For anyone close to 12 points, or within two years of passing their test, a single fixed penalty can end your licence entirely.","penalties":[{"label":"6 penalty points","note":"Mandatory endorsement","tone":"risk"},{"label":"Up to £1,000 fine","note":"Higher for goods vehicles","tone":"risk"},{"label":"Licence revoked","note":"If within 2 years of passing","tone":"risk"}],"issuesHeading":"The issues I examine","issuesIntro":"The law was rewritten in 2022 and is now much broader — but it is not unlimited, and the exceptions are real.","defenceIssues":[{"title":"Whether the device was held","body":"The offence requires holding the device. Hands-free use, and a phone in a cradle, are treated differently."},{"title":"Whether you were driving","body":"Being stationary in traffic is still driving. Being safely parked with the engine off generally is not."},{"title":"The contactless payment exception","body":"Using a phone to make a contactless payment while stationary, for goods or services received at the same time, is excepted."},{"title":"The emergency call exception","body":"Calling 999 or 112 in a genuine emergency, where it is unsafe or impracticable to stop, is a defence."},{"title":"The quality of the observation","body":"Where the case rests on what an officer saw in passing, that observation can be tested."},{"title":"Totting up consequences","body":"If six points would take you to 12, the fixed penalty should not be accepted without advice."}],"process":[{"title":"Before you accept the penalty","body":"Speak to me first if you have any existing points. The consequence may be larger than the notice suggests."},{"title":"Reviewing the allegation","body":"What was seen, from where, and for how long. Any footage is obtained."},{"title":"Advising on your options","body":"Whether an exception applies, and what contesting the matter is likely to involve."},{"title":"At court","body":"Representation at trial, or an exceptional hardship argument if totting up is engaged."}]}'::jsonb),
    ('no-insurance'::text, true, '{"headline":"Driving without insurance.","emphasis":"Strict liability, real options.","intro":"Strict liability does not mean no options. Special reasons, a genuine belief argument, and the employee exception are all available in the right cases.","penalties":[{"label":"6–8 mandatory points","note":"Or discretionary disqualification","tone":"risk"},{"label":"Unlimited fine","note":"Means-related","tone":"risk"},{"label":"Vehicle seizure","note":"Often at the roadside","tone":"risk"}],"issuesHeading":"The issues I examine","issuesIntro":"The offence is one of strict liability, so the work is usually directed at avoiding the endorsement rather than the conviction.","defenceIssues":[{"title":"Whether cover in fact existed","body":"Policies are frequently misread by all sides. Certificates, schedules and any extension of cover are checked directly with the insurer."},{"title":"Driving other cars","body":"Whether your own policy extended to the vehicle in question is a question of the policy wording, not of assumption."},{"title":"The employee exception","body":"An employee driving in the course of employment, who neither knew nor had reason to believe there was no cover, has a statutory defence."},{"title":"Special reasons — misled","body":"Where you were genuinely and reasonably led to believe cover was in place, the court may decline to endorse."},{"title":"Whether you were the driver","body":"As with any road traffic charge, the prosecution must prove you were driving on a road or public place."},{"title":"Recovering the vehicle","body":"Where the vehicle has been seized, prompt advice on release limits the cost."}],"process":[{"title":"The first conversation","body":"Bring the policy documents and any correspondence with the insurer. They usually decide the case."},{"title":"Checking the position","body":"The insurer is approached directly for confirmation of what was and was not covered on the day."},{"title":"Advising on your options","body":"Whether a defence exists, or whether the objective should be avoiding the points by special reasons."},{"title":"At court","body":"Representation at trial or at a special reasons hearing."}]}'::jsonb),
    ('failing-to-stop'::text, true, '{"headline":"Failing to stop or report.","emphasis":"Two separate charges.","intro":"Section 170 creates two distinct offences. A driver can satisfy one duty and breach the other. Each can be defended independently.","penalties":[{"label":"5–10 penalty points","note":"Per offence","tone":"risk"},{"label":"Unlimited fine","note":"Means-related","tone":"risk"},{"label":"Up to 26 weeks’ custody","note":"Most serious cases","tone":"risk"}],"issuesHeading":"The issues I examine","issuesIntro":"Because the duties are separate, the right analysis often narrows the case considerably.","defenceIssues":[{"title":"Knowledge of the accident","body":"You cannot fail to stop for something you did not know had happened. Minor contact is frequently not felt or heard."},{"title":"Whether you did stop","body":"The duty is to stop and, if required, give particulars. Whether that duty was met is a question of fact."},{"title":"The duty to report","body":"Where particulars were not exchanged, the accident must be reported as soon as reasonably practicable and within 24 hours."},{"title":"Whether it was an accident within the section","body":"The section applies to defined categories of damage and injury. Not every incident falls within it."},{"title":"Identity of the driver","body":"Where the allegation follows from a registration number, the prosecution must still prove who was driving."},{"title":"Totting up risk","body":"The points for these offences are high, and two charges can arise from one incident."}],"process":[{"title":"Early advice","body":"If you have been asked to attend an interview, speak to me before you do."},{"title":"Reviewing the allegation","body":"The damage said to have been caused, any footage, and what was reported and when."},{"title":"Advising on plea","body":"Each charge is considered separately, because the answer to one is often not the answer to the other."},{"title":"At court","body":"Representation at trial or in mitigation."}]}'::jsonb),
    ('driver-details'::text, true, '{"headline":"Failing to provide driver details.","emphasis":"Section 172.","intro":"The penalty is often harsher than the original offence: six points for not responding to a form. Reasonable diligence is a real defence — but it needs evidence.","penalties":[{"label":"6 mandatory points","note":"More than most speeding offences","tone":"risk"},{"label":"Up to £1,000 fine","note":"Means-related","tone":"risk"},{"label":"21 days to act","note":"Statutory declaration if convicted in absence","tone":"note"}],"issuesHeading":"The issues I examine","issuesIntro":"Most of these cases turn on whether the notice arrived and on what you did when it did.","defenceIssues":[{"title":"Whether the notice was received","body":"If the notice never reached you, you cannot have failed to respond to it. Service is for the prosecution to prove."},{"title":"Reasonable diligence","body":"Where you genuinely could not identify the driver despite reasonable diligence, a statutory defence is available."},{"title":"What you did to find out","body":"The defence succeeds on evidence: records kept, enquiries made, replies received. Contemporaneous material matters."},{"title":"Companies and fleet keepers","body":"Different obligations apply to a body corporate, and the systems in place for recording drivers become central."},{"title":"Whether a response was in fact sent","body":"Proof of posting, copies and email records can answer the allegation outright."},{"title":"Convicted without knowing","body":"Where you learn of a conviction only afterwards, a statutory declaration within 21 days can reopen the case."}],"process":[{"title":"Act quickly","body":"The time limits here are short and unforgiving, particularly where a statutory declaration is needed."},{"title":"Reviewing the correspondence","body":"Every notice, envelope, reply and proof of posting is gathered. The paper trail is the case."},{"title":"Advising on your options","body":"Whether service or reasonable diligence can be argued, and what the realistic outcome is."},{"title":"At court","body":"Representation at trial, or at the hearing that follows a statutory declaration."}]}'::jsonb),
    ('criminal-defence'::text, true, '{"headline":"General criminal defence.","emphasis":"Twenty years of it.","intro":"Alongside motoring work, John represents people facing criminal allegations in the magistrates’ court — from first arrest through to trial. The approach is the same: understand the case fully, explain it plainly, and prepare properly.","penalties":[{"label":"Free at the police station","note":"Legal aid in most cases","tone":"note"},{"label":"Advice before interview","note":"The stage that shapes everything after","tone":"note"},{"label":"Representation at court","note":"First hearing through to trial","tone":"note"}],"issuesHeading":"How John can assist","issuesIntro":"Most people meet the criminal process once. Knowing what happens next removes a great deal of the fear attached to it.","defenceIssues":[{"title":"At the police station","body":"Advice before and during interview, including whether to answer questions, give a statement or remain silent."},{"title":"Reviewing the evidence","body":"The prosecution case is obtained and examined properly before any decision on plea is taken."},{"title":"Advising on plea","body":"A frank assessment of the strength of the case and of the credit available for an early plea."},{"title":"Preparing for trial","body":"Witnesses, disclosure and any expert evidence are dealt with in good time rather than at the door of the court."},{"title":"Sentence","body":"Where conviction follows, mitigation is prepared with the supporting material that gives it weight."}],"process":[{"title":"The first conversation","body":"Tell me what has happened and what stage things have reached. There is no charge for that conversation."},{"title":"Understanding the case","body":"I obtain the evidence and go through it with you, in plain terms, before anything is decided."},{"title":"The decision on plea","body":"The choice is yours. My job is to make sure it is an informed one."},{"title":"At court","body":"Personal representation at every hearing, by the solicitor you have been speaking to throughout."}]}'::jsonb)
  ) as v (service_slug, published, content)
join public.services s on s.slug = v.service_slug
where not exists (select 1 from public.service_pages);

-- The draft fee schedule from the supplied reference. Seeded published
-- because that is what the site shows today. The figures, the VAT position
-- and the travel terms are all still unconfirmed (PRD §25) and the fees page
-- still says so — confirm them with John before launch.
insert into public.fees (title, price, published, sort_order, content)
select v.title, v.price, v.published, v.sort_order, v.content
from (values
    ('Police station'::text, '£400'::text, true, 0::integer, '{"description":"Any police station, England & Wales","included":["Pre-interview disclosure review","Private consultation before interview","Attendance at interview","Advice on bail or release conditions"]}'::jsonb),
    ('Single hearing'::text, '£600'::text, true, 10::integer, '{"description":"Magistrates’ Court — guilty plea or first appearance","included":["Full case review and evidence analysis","Pre-hearing consultation","All preparatory work","Court attendance and representation","Mitigation submissions where required"]}'::jsonb),
    ('First appearance & trial'::text, '£1,200'::text, true, 20::integer, '{"description":"Two-hearing case","included":["Full defence preparation","Evidence and disclosure review","Pre-trial correspondence","Attendance at both hearings","Trial advocacy"]}'::jsonb),
    ('Three-hearing case'::text, '£1,500'::text, true, 30::integer, '{"description":"First appearance, trial and sentence","included":["Preparation and correspondence","Attendance at all three hearings","Trial advocacy","Sentencing attendance","Inter-hearing consultation"]}'::jsonb),
    ('Exceptional hardship'::text, '£750'::text, true, 40::integer, '{"description":"Full preparation and hearing","included":["Detailed case analysis","Evidence gathering and preparation","Written submissions where required","Court representation"]}'::jsonb),
    ('Special reasons'::text, '£750 / £1,100'::text, true, 50::integer, '{"description":"Single or double hearing","included":["Preparation and evidence review","Expert evidence coordination where required","Written legal submissions","Court representation throughout"]}'::jsonb)
  ) as v (title, price, published, sort_order, content)

where not exists (select 1 from public.fees);

-- The verified reviews from John's ReviewSolicitors profile, seeded published
-- because they are what the homepage shows today. `content.source` names the
-- platform they were collected on: PRD §17 forbids presenting an invented
-- review as a verified one, and that field is what tells the two apart. Only
-- set it on a review that can be pointed at.
insert into public.testimonials (author, quote, rating, published, sort_order, content)
select v.author, v.quote, v.rating, v.published, v.sort_order, v.content
from (values
    ('Henry Parsons'::text, 'John explained the situation clearly, identified that the prosecution’s evidence had weaknesses, and negotiated a resolution that kept me on the road. He was the only solicitor I called who actually listened to the details before quoting me.'::text, 5::smallint, true, 0::integer, '{"matter":"Driving offences","source":"ReviewSolicitors"}'::jsonb),
    ('Joanna'::text, 'Fantastic service and excellent communication. Very reasonably priced and would highly recommend. Thank you!'::text, 5::smallint, true, 10::integer, '{"source":"ReviewSolicitors"}'::jsonb)
  ) as v (author, quote, rating, published, sort_order, content)

where not exists (select 1 from public.testimonials);

-- Categories, derived from the articles that use them.
insert into public.blog_categories (slug, name)
select v.slug, v.name
from (values
    ('drink-driving'::text, 'Drink Driving'::text),
    ('totting-up'::text, 'Totting Up'::text),
    ('mobile-phone'::text, 'Mobile Phone'::text),
    ('special-reasons'::text, 'Special Reasons'::text),
    ('speeding'::text, 'Speeding'::text),
    ('police-station'::text, 'Police Station'::text)
  ) as v (slug, name)

where not exists (select 1 from public.blog_categories);

-- The six legal guides. `published_at` is null: the static articles carry no
-- publication date and inventing one would date content John has not yet
-- approved. The blog admin sets it on first publish.
insert into public.blog_posts (slug, title, category_id, published, published_at, content)
select v.slug, v.title, c.id, v.published, v.published_at, v.content
from (values
    ('what-happens-after-a-drink-driving-arrest'::text, 'What happens after a drink driving arrest? A step-by-step guide'::text, 'drink-driving'::text, true, null::timestamptz, '{"excerpt":"From the roadside breath test to the magistrates’ court hearing — what to expect at each stage.","standfirst":"Most people arrested for drink driving have never been arrested before. Knowing the order things happen in removes some of the fear, and helps you understand where the decisions that matter actually fall.","readTime":"8 min read","icon":"glass","body":[{"heading":"At the roadside","paragraphs":["A police officer who has reasonable grounds to suspect that you have alcohol in your body, or who stops you after a moving traffic offence or a collision, can require a preliminary breath test at the roadside.","That roadside device is a screening tool. It is not the reading used to prosecute you. Its purpose is to establish whether there are grounds to arrest, and its result is not usually evidence of the offence itself."]},{"heading":"At the police station","paragraphs":["The evidential procedure takes place at the station, on an approved device. This is the reading the prosecution will rely on, and it is the stage at which most of the issues capable of affecting the outcome arise.","The procedure is prescriptive. The officer must follow it, must give you specific warnings, and in defined circumstances must offer you the option of replacing a breath specimen with blood or urine. Whether all of that happened correctly is a proper subject of scrutiny."],"list":["You are entitled to free legal advice at the police station, at any hour","That right applies before and during any interview","Asking for a solicitor does not make you look guilty, and does not delay matters as much as people expect"]},{"heading":"Charge and bail","paragraphs":["If you are charged, you will be given a charge sheet setting out the allegation and a date to attend the magistrates’ court. You are usually released on bail to that date.","Keep every document you are given. The charge sheet, the printout from the station device and any custody record all matter, and they are the first things a solicitor will ask to see."]},{"heading":"Before the hearing","paragraphs":["This is the stage where instructing a solicitor makes the greatest difference. The evidence can be requested and examined, the procedure at the station can be checked, and you can be advised properly on plea before you are asked to enter one.","It is much harder to undo a guilty plea entered at the first hearing than it is to take a short time to get advice first."]},{"heading":"At court","paragraphs":["Drink driving is heard in the magistrates’ court. If you plead not guilty, a trial date is set. If you plead guilty, or are convicted, the court moves to sentence.","On conviction the disqualification is a minimum of twelve months, and longer where the reading is high or there is a previous conviction within ten years. That is why the work done before the hearing matters so much."]},{"heading":"Where there is still room to argue","paragraphs":["Even where the offence itself is not in dispute, a special reasons argument can ask the court not to disqualify — for example where a drink was laced, where there was a genuine emergency, or where the distance driven was very short.","These arguments require evidence, and usually expert evidence. They are not put together on the morning of the hearing."]}],"relatedService":"/services/drink-driving"}'::jsonb),
    ('exceptional-hardship-what-the-court-looks-for'::text, 'Exceptional hardship: what the court is actually looking for'::text, 'totting-up'::text, true, null::timestamptz, '{"excerpt":"Most exceptional hardship arguments fail. This guide explains the legal test and the evidence you need.","standfirst":"Reaching twelve penalty points means a six-month disqualification unless the court is persuaded that it would cause exceptional hardship. The argument succeeds far less often than people expect, and it usually fails for reasons that were avoidable.","readTime":"6 min read","icon":"points","body":[{"heading":"The test is not inconvenience","paragraphs":["Every disqualification is inconvenient. Losing your licence makes work harder, family life harder and everything slower. None of that is exceptional, because it is true of every driver who is banned.","What the court is looking for is hardship that goes beyond the ordinary consequences of losing a licence. The clearest way to demonstrate that is to show the effect on people other than yourself."]},{"heading":"Hardship to other people carries the most weight","paragraphs":["Arguments that succeed tend to involve consequences for third parties: employees who would lose their jobs if the business could not operate, a dependant relative who relies on you for care and transport, or clients in a remote area who could not be reached another way.","An argument built only on the effect on you is much weaker, even where that effect is genuinely serious."]},{"heading":"Losing your job is not, by itself, enough","paragraphs":["Courts hear that a driver will lose their job in a large proportion of these applications. Standing alone, it rarely persuades.","What can persuade is what follows from it — that the mortgage cannot be paid and the family would lose their home, that a business would close and other people would be put out of work, or that a specific care arrangement would collapse."]},{"heading":"Bring evidence, not assertions","paragraphs":["This is where most applications come apart. The court is being asked to depart from a mandatory penalty, and it expects to be given a proper basis for doing so."],"list":["Employment contracts, payslips and correspondence from your employer","Business accounts, and evidence of what the business does and who it employs","Medical evidence where a dependant’s health or care needs are relied on","Statements from the people affected — and, where possible, their attendance at court","Evidence about public transport, taxis or other drivers, and why they would not solve the problem"]},{"heading":"You will be asked questions","paragraphs":["You will usually give evidence yourself, on oath, and you can expect to be challenged on whether the hardship is really exceptional and whether there is another way around it.","Preparation for that is part of the work. So is knowing which questions are coming."]},{"heading":"You generally get one go","paragraphs":["Where the court accepts an exceptional hardship argument, the same circumstances cannot usually be relied on again within the following three years.","That is worth knowing before the argument is run, because it affects whether this is the right occasion to run it."]}],"relatedService":"/services/exceptional-hardship"}'::jsonb),
    ('mobile-phone-driving-law-changes'::text, 'The 2022 mobile phone driving law changes explained'::text, 'mobile-phone'::text, true, null::timestamptz, '{"excerpt":"The law was fundamentally rewritten. This guide explains exactly what is now prohibited.","standfirst":"In March 2022 the law on using a mobile phone while driving was rewritten and significantly widened. A great deal that was lawful before is not lawful now, and six points is a serious penalty for anyone with existing points on their licence.","readTime":"5 min read","icon":"phone","body":[{"heading":"What changed","paragraphs":["The previous law was directed at interactive communication — calls, texts and similar. That left a gap: courts had accepted that some standalone uses of a phone, such as recording a video, did not fall within the wording.","The rewritten regulations close that gap. The offence now covers using a hand-held device for a much broader range of functions, whether or not it involves communicating with anyone."]},{"heading":"What is now prohibited","paragraphs":["Holding a phone or similar device while driving and using it for essentially any of its functions is now caught."],"list":["Making or receiving a call","Sending, receiving or reading any kind of message","Taking photographs or recording video, and scrolling through them","Browsing the internet or using apps","Selecting music or other stored content","Using it to check the time, or simply unlocking it"]},{"heading":"The word that matters is ''held''","paragraphs":["The offence turns on holding the device. A phone in a proper cradle, operated in a way that does not involve holding it, is treated differently — though driving without proper control remains a separate offence if attention is taken from the road.","Hands-free use is not caught by this particular offence. That does not make it risk-free in every circumstance."]},{"heading":"Stationary in traffic is still driving","paragraphs":["One of the most common misunderstandings is that a queue of traffic or a red light stops you from driving for these purposes. It does not.","Being safely parked with the engine off is a different matter."]},{"heading":"The exceptions that do exist","paragraphs":["The regulations kept some genuine exceptions, and they can be decisive in the right case."],"list":["Calling 999 or 112 in a genuine emergency, where it is unsafe or impracticable to stop","Making a contactless payment while stationary, for goods or services received at the same time — a drive-through or a toll barrier, for example","Using a device for remote-controlled parking as designed"]},{"heading":"Why six points is not a minor matter","paragraphs":["Six points is half of the twelve that trigger a totting-up disqualification. For a driver who already has six points, accepting a fixed penalty means a ban.","For anyone within two years of passing their test, six points means the licence is revoked and the test must be taken again. In both situations, the notice should not be accepted without advice."]}],"relatedService":"/services/mobile-phone"}'::jsonb),
    ('laced-drinks-and-drink-driving'::text, 'Laced drinks: can it really prevent a drink driving disqualification?'::text, 'special-reasons'::text, true, null::timestamptz, '{"excerpt":"Sometimes — but the legal test is stringent. This guide sets out what the court requires.","standfirst":"The laced drink argument is well known and frequently misunderstood. It is a real argument, and it does succeed — but it is not a defence to the offence, and it is not established simply by saying it happened.","readTime":"7 min read","icon":"spark","body":[{"heading":"It is not a defence to the charge","paragraphs":["This is the point people most often get wrong. If you were over the limit and you drove, the offence is committed, whatever you believed you were drinking.","A laced drink argument is a special reasons argument. You are convicted of the offence, but you ask the court to exercise its discretion not to disqualify you. The conviction stands; the ban is what is in issue."]},{"heading":"What you have to establish","paragraphs":["The burden is on you, and there are three limbs the court will look at."],"list":["That your drink was in fact laced, or that you were given alcohol without knowing it","That you did not know and had no reason to suspect that what you were drinking was or had been strengthened","That, but for the additional alcohol, you would have been under the limit"]},{"heading":"The third limb is where most arguments fail","paragraphs":["It is not enough that someone added alcohol to your drink. You have to show that without it you would have been below the limit.","If you had already drunk enough to be over the limit on your own account, the lacing made no difference to whether the offence was committed, and the argument does not get off the ground."]},{"heading":"You will usually need expert evidence","paragraphs":["Establishing that third limb normally requires a forensic report. An expert works from what you drank, when, your body weight and the reading obtained, and calculates what your level would have been without the added alcohol.","Courts are used to seeing these reports and are generally unwilling to accept the argument without one."]},{"heading":"The court also asks whether you should have realised","paragraphs":["Even where the calculation works, the court will consider whether you ought to have appreciated that you were unfit or over the limit before you decided to drive.","If you felt noticeably affected and drove anyway, that can defeat the argument even where the drink was genuinely laced."]},{"heading":"What helps","paragraphs":["Evidence gathered early is worth far more than recollection months later."],"list":["The name of the person who laced the drink, and ideally their evidence","Witnesses who were with you and can say what you drank","Receipts, card statements or venue CCTV establishing what was bought","A clear, contemporaneous account of the evening while it is fresh"]},{"heading":"It is a discretion, not an entitlement","paragraphs":["Even where all three limbs are established, the court is not obliged to allow you to keep your licence. It retains a discretion, and it will exercise it having regard to all the circumstances.","That is why these arguments are prepared properly or not at all."]}],"relatedService":"/services/special-reasons"}'::jsonb),
    ('notice-of-intended-prosecution'::text, 'Received a Notice of Intended Prosecution? Here’s what to do'::text, 'speeding'::text, true, null::timestamptz, '{"excerpt":"A NIP triggers strict time limits and legal obligations. Missing deadlines can worsen your position.","standfirst":"A Notice of Intended Prosecution is not a charge, and it is not a fine. It is the start of a process with short deadlines attached, and the way you respond to it can matter more than the original allegation.","readTime":"4 min read","icon":"mail","body":[{"heading":"What the notice is","paragraphs":["For a range of offences — speeding, careless driving and some others — the police must warn the driver that prosecution is being considered. For camera-detected offences that warning arrives by post, addressed to the registered keeper.","It normally arrives with a separate request for driver details under section 172."]},{"heading":"The fourteen-day rule, and what it actually means","paragraphs":["The notice must generally be served on the registered keeper within fourteen days of the alleged offence. Service is on the keeper, not on the driver, so a notice that reaches a company promptly is properly served even if it takes longer to reach the person who was driving.","Late service can be fatal to the prosecution, but the point needs to be taken correctly rather than assumed. Keep the envelope."]},{"heading":"The request for driver details is the urgent part","paragraphs":["The obligation to identify the driver carries a twenty-eight day deadline, and ignoring it is far more serious than most people realise.","Failing to provide driver details carries six penalty points — often more than the speeding offence that prompted the notice, and enough on its own to put a licence at risk."]},{"heading":"What to do","paragraphs":["In order, and without delay:"],"list":["Note the date the notice arrived, and keep the envelope","Do not ignore it, and do not put it aside to deal with later","If you genuinely cannot identify the driver, record what enquiries you make and when","Take advice before responding if you already have points on your licence","Return the response within the time limit, by a method that gives you proof of posting"]},{"heading":"If you cannot identify the driver","paragraphs":["There is a statutory defence where you could not, with reasonable diligence, establish who was driving. It is a real defence, but it succeeds on evidence rather than assertion.","That means showing what you actually did: who you asked, when, what records you checked and what answers you received. Contemporaneous notes are worth a great deal here."]},{"heading":"Think before accepting a fixed penalty","paragraphs":["A fixed penalty is often the sensible course. But if the points would take you to twelve, accepting it means a disqualification, and the opportunity to argue exceptional hardship at a hearing is lost.","Check your existing points before you sign anything."]}],"relatedService":"/services/speeding"}'::jsonb),
    ('answering-questions-in-a-police-interview'::text, 'Should you answer questions in a police interview?'::text, 'police-station'::text, true, null::timestamptz, '{"excerpt":"The decision to answer, give a statement, or remain silent is one of the most important decisions in any case.","standfirst":"There is no single right answer, and anyone who gives you one without knowing what the police have is guessing. What there is, is a way of approaching the decision — and one thing you should always do first.","readTime":"6 min read","icon":"shield","body":[{"heading":"Get a solicitor first. It is free.","paragraphs":["Advice at the police station is free to everyone, at any hour, regardless of means. It is not a service you have to qualify for and it is not something you are charged for afterwards.","Asking for a solicitor does not suggest guilt, and it does not add the delay people imagine. It is the single most useful thing you can do at that stage."]},{"heading":"Why disclosure matters before anything else","paragraphs":["Before an interview, your solicitor is entitled to ask the officer what the allegation is and what evidence there is to support it. That conversation is the basis of every decision that follows.","You cannot sensibly decide whether to answer questions when you do not know what is being put to you. Neither can anyone advising you."]},{"heading":"The three options","paragraphs":["Broadly, there are three courses, and each is right in different circumstances."],"list":["Answering questions — where you have a clear account that is supported by the evidence, and putting it early can resolve matters","A prepared statement — a written account handed in, after which you decline to answer questions, giving your account without being drawn beyond it","No comment — where disclosure is inadequate, where the position is genuinely unclear, or where you are unwell or unfit to be interviewed"]},{"heading":"What the caution really means","paragraphs":["The caution warns that it may harm your defence if you do not mention, when questioned, something you later rely on in court. That is the adverse inference, and it is why silence is not automatically the safe option.","But an inference can only be drawn in defined circumstances, and it cannot be drawn where you remained silent on legal advice for a reason that was proper at the time. That is another reason the advice itself matters."]},{"heading":"A prepared statement is often the middle course","paragraphs":["It puts your account on record at the earliest stage, which addresses the risk of an adverse inference, while avoiding hours of questioning about matters you may not remember precisely.","It has to be drafted carefully. An account that is inaccurate in a detail can cause more difficulty later than saying nothing would have."]},{"heading":"Things worth knowing","paragraphs":[],"list":["A voluntary interview is still a formal interview, under caution, with the same consequences","You are entitled to free legal advice at a voluntary interview too","You can ask for a break to speak to your solicitor privately at any point","Nothing said in the interview room is off the record"]},{"heading":"The stage that shapes everything after","paragraphs":["Cases are frequently decided by what happens in the interview room, long before anyone reaches a courtroom. An account given without advice, under pressure and without knowing what the police hold, can be very difficult to move away from later.","John has attended police stations since 2003. If you have been asked to attend an interview, speak to him before you go."]}],"relatedService":"/police-station"}'::jsonb)
  ) as v (slug, title, category_slug, published, published_at, content)
left join public.blog_categories c on c.slug = v.category_slug
where not exists (select 1 from public.blog_posts);

-- Site settings. Only the facts that are actually known are seeded. No
-- telephone number, WhatsApp number, TidyCal URL or SRA number appears here,
-- because none has been confirmed and PRD §25 forbids inventing one. The site
-- omits each of those routes entirely until it is set.
insert into public.site_settings (key, value)
select v.key, v.value
from (values
    ('name'::text, '"John Violaris"'::jsonb),
    ('role'::text, '"Criminal Defence Solicitor"'::jsonb),
    ('roleLong'::text, '"Criminal Defence Solicitor & Motoring Specialist"'::jsonb),
    ('initials'::text, '"JV"'::jsonb),
    ('jurisdiction'::text, '"England & Wales"'::jsonb),
    ('url'::text, '"https://johnviolaris.com"'::jsonb),
    ('secondaryUrl'::text, '"https://drivingjustice.co.uk"'::jsonb),
    ('email'::text, '"contact@johnviolaris.com"'::jsonb),
    ('responseTime'::text, '"Response within 24 hours"'::jsonb),
    ('countryCode'::text, '"44"'::jsonb)
  ) as v (key, value)

where not exists (select 1 from public.site_settings);
